cypress_script:
describe('API endpoint documentation list', () => {
  it('should display the API list correctly', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('h1').contains('Automation Practice for API Testing');
    cy.get('h2').contains('APIs List for practice');
    cy.get('a').contains('API 1: Get All Products List').should('be.visible');
    cy.get('a').contains('API 2: POST To All Products List').should('be.visible');
    cy.get('a').contains('API 3: Get All Brands List').should('be.visible');
    cy.get('a').contains('API 4: PUT To All Brands List').should('be.visible');
  });

  it('should not change the URL when clicking on an invalid link', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('a').contains('Invalid API Link').click();
    cy.url().should('eq', 'https://automationexercise.com/api_list');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('API endpoint documentation list', () => {
  test('should display the API list correctly', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await expect(page.locator('h1')).toContainText('Automation Practice for API Testing');
    await expect(page.locator('h2')).toContainText('APIs List for practice');
    await expect(page.locator('a').withText('API 1: Get All Products List')).toBeVisible();
    await expect(page.locator('a').withText('API 2: POST To All Products List')).toBeVisible();
    await expect(page.locator('a').withText('API 3: Get All Brands List')).toBeVisible();
    await expect(page.locator('a').withText('API 4: PUT To All Brands List')).toBeVisible();
  });

  test('should not change the URL when clicking on an invalid link', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await page.click('text=Invalid API Link');
    await expect(page).toHaveURL('https://automationexercise.com/api_list');
  });
});
